import { NoiseGateSettings, normalizeNoiseGate } from './noiseGateSettings';

// Same envelope, hysteresis and attack/release as the live worklet, applied
// to a copy before offline effects rendering. The captured take stays raw.
export const applyOfflineNoiseGate = (
  samples: Float32Array,
  sampleRate: number,
  settings: NoiseGateSettings,
) => {
  const result = samples.slice();
  const normalized = normalizeNoiseGate(settings);
  if (!normalized.enabled) return result;
  const detectorDecay = Math.exp(-1 / (0.02 * sampleRate));
  const attack = Math.exp(-Math.log(1000) / (0.002 * sampleRate));
  const release = Math.exp(
    -Math.log(1000) / ((normalized.release * sampleRate) / 1000),
  );
  const threshold = Math.pow(10, normalized.threshold / 20);
  let envelope = 0;
  let gain = 0;
  let open = false;
  for (let i = 0; i < result.length; i++) {
    const sample = result[i];
    envelope = Math.max(Math.abs(sample), envelope * detectorDecay);
    if (envelope >= threshold) open = true;
    else if (envelope < threshold * 0.5) open = false;
    const target = open ? 1 : 0;
    const coefficient = target > gain ? attack : release;
    gain = target + (gain - target) * coefficient;
    result[i] = sample * gain;
  }
  return result;
};
